a<-commandArgs(TRUE)[1];x<-read.delim(file.path(a,'results.tsv'));stopifnot(nrow(x)==48,!anyDuplicated(x[c('trait','panel','target','condition','z_method')]),all(abs(x$signed_r)<1));z<-(x$target_z-x$signed_r*x$condition_z)/sqrt(1-x$signed_r^2);p<-2*pnorm(-abs(z));stopifnot(max(abs(z-x$residual_z))<1e-12,max(abs(p-x$nominal_normal_p))<1e-12);cat('verified 48 residual statistics and two-sided normal tails\n')
